#!/bin/bash
# Generates Sources/Explorer/BuildInfo.swift with the current build timestamp.
# Run before `swift build` during development.
# The generated file is not committed (git assume-unchanged).
set -euo pipefail

TIMESTAMP=$(date "+%Y-%m-%d %H:%M:%S")
REPO_ROOT="$(cd "$(dirname "$0")/.." && pwd)"

cat > "$REPO_ROOT/Sources/Explorer/BuildInfo.swift" << EOF
// Auto-generated by scripts/gen-build-info.sh — do not commit.
let buildTimestamp = "$TIMESTAMP"
EOF
